object NewBalanceChapter1Part2 {
    val quests = listOf(
        Quest("CH1-045",1,45,"A Staff for Lance",category="Ring of Water",giver="Lance",location="Ring of Water",prerequisites="Chapter 1; Ring of Water progression; before the first trip to Jharkendar.",summary="Speak with Lance during the Ring of Water/Water Mage preparations and obtain the staff he needs through the local quest chain.",walkthroughSteps=listOf("Speak with Lance during the Ring of Water/Water Mage preparations and obtain the staff he needs through the local quest chain. Bring the requested staff back to Lance before the expedition moves on."),reward="Experience and completion of Lance's preparation task.",warnings="MISSABLE: complete this before entering Jharkendar for the first time.",searchTags=listOf("a staff for lance","ring of water","lance")),
        Quest("CH1-046",1,46,"Crazy Fellan",category="Khorinis - Harbor District",giver="Alwin",location="Khorinis - Harbor District",prerequisites="Chapter 1; Harbor District.",summary="Alwin is being driven mad by Fellan's constant hammering.",walkthroughSteps=listOf("Alwin is being driven mad by Fellan's constant hammering. Speak to Fellan and confront him; the quest is resolved by beating him in a fight rather than killing him. Talk to Fellan after the fight, then report back to Alwin."),reward="30 gold and 400 XP.",warnings="Use a non-lethal beating; killing Fellan is unnecessary and can remove future content.",searchTags=listOf("crazy fellan","khorinis - harbor district","alwin")),
        Quest("CH1-047",1,47,"Information for Garvell",category="Khorinis - Harbor District",giver="Garvell",location="Khorinis - Harbor District",prerequisites="Chapter 1; before Chapter 3 for the early information stages.",summary="Garvell wants information about the situation in Khorinis.",walkthroughSteps=listOf("Garvell wants information about the situation in Khorinis. Buy Rangar beer and question him about the orcs, then later learn the paladins' true mission by progressing far enough to speak with Lord Hagen. Return to Garvell with each useful piece of information."),reward="About 250 XP for the Rangar information and 500 XP for the Lord Hagen information.",warnings="The Lord Hagen information is worth more than the early rumor; return after your main-story access improves.",searchTags=listOf("information for garvell","khorinis - harbor district","garvell")),
        Quest("CH1-048",1,48,"Alrik's Sword",category="Khorinis - Harbor District",giver = "Alrik",location="Khorinis - Harbor District",prerequisites="Chapter 1 or 2: speak to Alrik; from later chapters first fight him in the harbor arena.",summary="Recover Alrik's sword from merchant Jora and return it to Alrik in Khorinis harbor.",walkthroughSteps=listOf("Find Alrik in Khorinis's harbor district and ask why he no longer has his sword.","Visit merchant Jora in the marketplace. If you recovered Jora's stolen gold and requested a share as your reward, Jora can hand over the sword for free.","Otherwise buy Alrik's sword from Jora for 100 gold.","Give the sword back to Alrik to complete the quest and unlock his harbor arena challenges."),reward="300 XP for returning Alrik's sword; +1 Rhetoric if Jora gives it free in the favorable dialogue.",warnings="The no-cost option through Jora may also award a rhetoric point. Source: https://rpgrussia.com/threads/mech-alrika.66809/",searchTags=listOf("alrik's sword","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-049",1,49,"Lucia",category="Khorinis - Harbor District",giver="Bromor",location="Khorinis - Harbor District",prerequisites="Start Where Are the Missing People?; speak with Bromor in Khorinis harbor.",summary="Investigate the missing courtesan Lucia and trace her from the harbor brothel to Jharkendar.",walkthroughSteps=listOf("After starting Where Are the Missing People?, question Bromor at Khorinis's harbor brothel about the missing residents.","Ask Nadja about Lucia for additional clues; Bromor charges 50 gold for a private conversation with Nadja.","Search the bandit camp behind Sekob's farm and read Lucia's letter in a tent.","Tell Elvrich what you found, rescuing him from the bandits on the path to the Water Mages if needed.","Eventually find Lucia alive in the bandit camp in Jharkendar."),reward="Optional: 100 XP for speaking privately with Nadja, and 100 XP for informing Elvrich. The guide does not specify a separate final completion reward.",warnings="Bromor is the source's starting NPC; Nadja is an optional informant and Elvrich a related contact. Source: https://rpgrussia.com/threads/ljusija.67274/",searchTags=listOf("lucia","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-050",1,50,"Bromor's Golden Vase",category="Khorinis - Harbor District",giver = "Bromor",location="Khorinis - Harbor District",prerequisites="Start Where Are the Missing People? and ask Bromor about Lucia.",summary="Retrieve the valuable golden vase taken by Lucia from Bromor's brothel.",walkthroughSteps=listOf("After starting Where Are the Missing People?, speak with Bromor about Lucia and his missing golden vessel.","Find the bandits in the forest beyond Sekob's farm.","Search their camp for Bromor's stolen golden vase.","Return the vase to Bromor in the Khorinis harbor brothel."),reward="400 XP and a complimentary visit with Nadja.",warnings="Returning the vase opens a complimentary visit with Nadja. Source: https://rpgrussia.com/threads/zolotaja-vaza-bromora.67276/",searchTags=listOf("bromor's golden vase","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-051",1,51,"A Night with Nadja",category="Khorinis - Harbor District",giver="Bromor",location="Khorinis - Harbor District",prerequisites="Chapter 1; Missing People investigation active.",summary="Ask Bromor about the missing woman and his stolen valuable.",walkthroughSteps=listOf("Ask Bromor about the missing woman and his stolen valuable. Search the bandits in the forest behind Sekob's farm; the missing golden vase/cup is among their loot. Return the item to Bromor."),reward="400 XP and free access to the Night with Nadja quest reward route.",warnings="Completing this can earn you a free night with Nadja, which is useful for the linked quest.",searchTags=listOf("a night with nadja","khorinis - harbor district","bromor")),
        Quest("CH1-052",1,52,"The Experiment",category="Khorinis - Harbor District",giver="Nadja / Bromor",location="Khorinis - Harbor District",prerequisites="Chapter 1; pay Bromor or complete Bromor's Golden Vase.",summary="Arrange a night with Nadja at the Red Lantern.",walkthroughSteps=listOf("Arrange a night with Nadja at the Red Lantern. Pay the normal fee, or first return Bromor's stolen golden vase to obtain the encounter for free. Follow Nadja upstairs and complete her dialogue."),reward="350 XP and +10 stamina.",warnings="Doing Bromor's quest first avoids the 50-gold fee.",searchTags=listOf("the experiment","khorinis - harbor district","nadja / bromor")),
        Quest("CH1-053",1,53,"Man in the Guise of a Beast",category="Khorinis - Harbor District",giver="Ignaz",location="Khorinis - Harbor District",prerequisites="Finish Ignaz's Experiment quest.",summary="Reverse an experiment that transformed Ignaz's apprentice into a beast.",walkthroughSteps=listOf("After completing Experiment, ask Ignaz about his missing apprentice.","Investigate by speaking to Mika, Akil, Orlan, and Sagitta in that order.","When the transformed apprentice appears near Sagitta, visit Vatras for a scroll that can restore its mind.","Return to Sagitta's cave, speak to her and use the scroll near the shadowbeast.","Speak with Sagitta again and return to Ignaz for your reward."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="This is an index-guided quick solution. Exact item counts, coordinates and reward values can differ with New Balance updates; use the linked source record when a build-specific detail matters.",searchTags=listOf("man in the guise of a beast","khorinis - harbor district","local quest giver in khorinis - harbor district","ignaz")),
        Quest("CH1-054",1,54,"Trouble with the Militia",category="Khorinis - Harbor District",giver="Farim",location="Khorinis - Harbor District",prerequisites="Chapter 1; Harbor District.",summary="Speak with Farim about the militia harassing the fishermen.",walkthroughSteps=listOf("Speak with Farim about the militia harassing the fishermen. Go to Martin in the harbor and raise the issue; choose the dialogue that gets the guards to ease off. Return to Farim with the result."),reward="250 XP from Farim plus an aquamarine; 50 XP is available during the Martin dialogue.",warnings="Resolve it through Martin rather than starting violence with the militia.",searchTags=listOf("trouble with the militia","khorinis - harbor district","farim")),
        Quest("CH1-055",1,55,"Fish Soup for Farim",category="Khorinis - Harbor District",giver = "Farim",location="Khorinis - Harbor District",prerequisites="Complete Farim's Problem with the Militia.",summary="Ask Edda to make Farim a restorative fish soup, then return it to the sick fisherman.",walkthroughSteps=listOf("Complete Farim's Problem with the Militia and ask him if he needs more help.","Farim gives you five fish and sends you to Edda in the harbor.","Collect the ingredients Edda requests: ten fish, five seraphis herbs, one cheese, one red pepper and one bottle of rum.","Give the ingredients to Edda and receive the special fish soup.","Bring the soup back to Farim; he rewards you with fishing knowledge and your choice of shellfish or a black pearl."),reward="600 XP when delivering the soup; choose 18 mollusks or 1 black pearl, plus a fishing book. Intermediate conversations/preparation grant additional XP.",warnings="Follow the prerequisites and visit the named NPC before collecting goods. Source: https://rpgrussia.com/threads/uxa-dlja-farima.66770/",searchTags=listOf("fish soup for farim","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-056",1,56,"The Sunken Ship",category="Khorinis - Harbor District",giver="Farim",location="Khorinis - Harbor District",prerequisites="Complete Farim's earlier fishing/food task; before Chapter 3.",summary="Farim tells you about a wreck off the coast near the old lighthouse.",walkthroughSteps=listOf("Farim tells you about a wreck off the coast near the old lighthouse. Swim/div dive to the wreck and search it carefully for the quest sack/cargo. Bring what you recover back to Farim."),reward="250 gold and useful loot including a silver ring, red pepper and a piece of magic ore.",warnings="Save before a long dive if your stamina/air supply is low.",searchTags=listOf("the sunken ship","khorinis - harbor district","farim")),
        Quest("CH1-057",1,57,"Ore Shipment",category="Khorinis - Harbor District",giver = "Viper",location="Khorinis - Harbor District",prerequisites="Start through Viper in Chapter 1; access to the Valley of Mines and Xardas is required to finish in Chapter 2–4.",summary="Track Viper's hidden ore shipment through Snipes, Aleph and Xardas, then retrieve the stash.",walkthroughSteps=listOf("Speak repeatedly with Viper at Kardif's tavern; agree to give him 100 pieces of ore from the missing shipment to activate the search.","Find Snipes at Lobart's farm and remind him of the old job. He says Aleph hid the ore near the Valley of Mines.","In Chapter 2, search the goblin cave close to Marcos's camp, inspect Aleph's remains and take his bone.","Report Aleph's death to Viper, then bring the bone to Xardas, who summons Aleph's ghost; defeat the hostile spirit after learning the hiding place.","Back in the Valley of Mines, locate the rock in the river near the entrance descent and swim through the underwater passage into a small grotto.","Defeat the skeleton guardian, dig up the ore package and collect its 300 pieces of ore.","Return with the ore to Snipes and Viper to finish the quest."),reward="Completion: 1,000 XP from Snipes, 500 XP from Viper and a Stamina Elixir. Earlier investigation stages award additional XP; the cache holds 300 magic ore, including the amount promised to Viper.",warnings="Do not postpone until Chapter 5, when Xardas is no longer available. Source: https://rpgrussia.com/threads/gruz-rudy.67166/",searchTags=listOf("ore shipment","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-058",1,58,"Weapons for Gonzales",category="Khorinis - Harbor District",giver = "Gonzales",location="Khorinis - Harbor District",prerequisites="Speak to Gonzales in Chapter 1; Tactical Advantage in the Valley of Mines requires Chapter 2.",summary="Find an eastern assassin sword for Gonzales, who dislikes the local blades.",walkthroughSteps=listOf("Find Gonzales at Kardif's harbor tavern or Bromor's brothel and ask about the sword he lost.","He requests a weapon from the East, such as an assassin's sword.","In Chapter 2, accept and complete Parcival's Tactical Advantage assignment in the Valley of Mines.","Obtain the assassin sword awarded for that task and take it to Gonzales.","Afterward Gonzales can teach heat resistance."),reward="2,000 XP and 1,000 gold; unlocks heat-resistance training from Gonzales.",warnings="Follow the prerequisites and visit the named NPC before collecting goods. Source: https://rpgrussia.com/threads/oruzhie-dlja-gonsalesa.66951/",searchTags=listOf("weapons for gonzales","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-059",1,59,"The Cursed Lighthouse",category="Khorinis - Harbor District",giver = "Jack",location="Khorinis - Harbor District",prerequisites="Talk to Jack before Chapter 5; later stages require Greg in Jharkendar and progress in Jack's Pipe.",summary="Investigate the offshore haunted lighthouse and discover why the ghost of Stefan cannot rest.",walkthroughSteps=listOf("Ask Jack about the haunted lighthouse out at sea. Sail to its island and defeat the two bandits outside.","Enter the lighthouse, take its teleport ring, collect the silver ring on the stairs and press the hidden symbol near the top.","Ask Hanna about the inscribed ring and Xardas about the symbol and the curse.","Use Xardas's Summon Ghost scroll at the skeleton on top of the lighthouse and speak to Stefan's ghost below.","Ask Kardif and Jack about the pirate known as Kelevra. Once Greg is in Jharkendar, discuss Jack's pipe with Greg to learn Kelevra is Jack.","Talk Jack into visiting the offshore lighthouse on the following day, then speak to Stefan.","With at least 40 rhetoric, persuade Stefan not to kill Jack before lighting the beacon, or accept one of the harsher outcomes.","Finish the lighthouse confrontation and report to Jack where possible."),reward="Peaceful 40-Rhetoric ending: 3,000 XP, Jack's silver rapier and +1 Rhetoric from securing Stefan's promise. Other endings give different loot/outcomes; investigation also awards intermediate XP.",warnings="A peaceful outcome protecting Jack requires 40 rhetoric. Igniting the light without Stefan's promise may result in Jack's death. Source: https://rpgrussia.com/threads/prokljatyj-majak.66900/",searchTags=listOf("the cursed lighthouse","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-060",1,60,"Bandits in Jack's Lighthouse",category="Khorinis - Harbor District",giver="Jack",location="Khorinis - Harbor District",prerequisites="Chapter 1; Harbor District.",summary="Travel to Jack's lighthouse in the eastern forest and clear out the bandits occupying it.",walkthroughSteps=listOf("Travel to Jack's lighthouse in the eastern forest and clear out the bandits occupying it. Search the lighthouse and the bandit bodies, then return to Jack and tell him the place is safe. Jack can then move back to his lighthouse."),reward="900 XP and a sextant; further dialogue at the lighthouse can give an additional pirate-song reward.",warnings="The bandits are stronger than the first city thugs, so approach after acquiring basic armor and a reliable weapon.",searchTags=listOf("bandits in jack's lighthouse","khorinis - harbor district","jack")),
        Quest("CH1-061",1,61,"Accidental Courier",category="Khorinis - Harbor District",giver = "Nagur",location="Khorinis - Harbor District",prerequisites="Ask Kardif about work and pay him for the special-job lead to Nagur.",summary="Choose whether to deliver Baltram's parcel to Nagur for the Thieves' Guild or report him to Lord Andre.",walkthroughSteps=listOf("Pay Kardif for information about special work, then meet Nagur at his harbor tavern.","Negotiate a 50/50 division with Nagur; he orders you to pose as Baltram's courier.","Speak with Baltram in the marketplace and take the assignment to pick up goods from Akil's farm.","If preserving the Thieves' Guild route, collect the parcel from Akil and deliver it to Nagur instead of Baltram.","Wait one day and return to Nagur for your share.","Alternatively, report Nagur to Lord Andre immediately after receiving his proposal; this damages your relationship with the Thieves' Guild."),reward="Nagur delivery: 120 gold and 500 XP across parcel pickup, delivery and payout; +1 Rhetoric possible. Report Nagur instead: 150 XP, 150 gold, +3 Innos karma (militia: +15 salary).",warnings="Reporting Nagur to Lord Andre is an exclusive alternative to delivering the parcel for him. Source: https://rpgrussia.com/threads/kurer-po-oshibke.66773/",searchTags=listOf("accidental courier","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-062",1,62,"Halvor's Fish",category="Khorinis - Harbor District",giver="Stinking Note / Halvor",location="Khorinis - Harbor District",prerequisites="Complete the bandit raid at the cave near Akil's farm and retrieve the strange fish with the Stinking Note.",summary="Use the bandits' incriminating note found inside a fish to expose or bargain with Halvor, the harbor fishmonger.",walkthroughSteps=listOf("Clear the bandit cave near Akil's farm and search the chest for a strange fish.","Open the fish in your inventory and read the Stinking Note that identifies the fence.","Speak to Halvor at his fish stall in the Khorinis harbor and confront him with the evidence.","Either agree to keep quiet in exchange for access to Halvor's special fish, or report him to Lord Andre.","Remember that turning him in affects the peaceful route into the Thieves' Guild."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="The incriminating note is a discovered-object trigger; the choice to report Halvor changes later Thieves' Guild interactions.",searchTags=listOf("halvor's fish","khorinis - harbor district","local quest giver in khorinis - harbor district")),
        Quest("CH1-063",1,63,"Lehmar's Ledger",category="Khorinis - Harbor District",giver="Hidden / Lehmar",location="Khorinis - Harbor District",prerequisites="Chapter 1; learn pickpocketing.",summary="Pickpocket Lehmar and steal his debt ledger.",walkthroughSteps=listOf("Pickpocket Lehmar and steal his debt ledger. You can give the ledger to only one interested NPC, so decide which reward you want before handing it over. Thorben gives the strongest experience/karma￾oriented reward, Coragon gives a special beer, and Hanna gives a gemstone reward."),reward="Thorben: 1,500 XP, +5 Innos karma and +1 LP. Coragon: 300 XP plus special beer. Hanna: 300 XP plus an emerald.",warnings="ONE-RECIPIENT CHOICE: Thorben, Coragon or Hanna. Save before handing over the ledger if you want to compare rewards.",searchTags=listOf("lehmar's ledger","khorinis - harbor district","hidden / lehmar")),
        Quest("CH1-064",1,64,"Wine from Archolos",category="Khorinis - Harbor District",giver="Vadius",location="Khorinis - Harbor District",prerequisites="Optional Path of the Cursed content installed/enabled.",summary="Find the drunk Vadius in the harbor, speak with him and give him schnapps to get the full story.",walkthroughSteps=listOf("Find the drunk Vadius in the harbor, speak with him and give him schnapps to get the full story. Search the forest behind Akil's farm near the Innos statue for the special Archolos wine. Drink/inspect it as appropriate, then return to Vadius and finish the dialogue; an additional confrontation may follow."),reward="Several small XP stages; the special wine grants +2 HP, with further XP from the final confrontation.",warnings="This quest only exists with the relevant optional submod/content enabled.",searchTags=listOf("wine from archolos","khorinis - harbor district","vadius")),
        Quest("CH1-065",1,65,"Ship Rats",category="Khorinis - Harbor District",giver="Paladin ship crew",location="Khorinis - Harbor District",prerequisites="Chapter 1 or later; requires legitimate access to the paladin ship.",summary="Once you can board the paladin ship, go below deck into the hold and kill all six rats infesting it.",walkthroughSteps=listOf("Once you can board the paladin ship, go below deck into the hold and kill all six rats infesting it. Return to the crew member who raised the problem and report the hold clear."),reward="300 XP.",warnings="Do not force your way onto the ship if doing so would turn the paladins hostile; wait for legitimate access.",searchTags=listOf("ship rats","khorinis - harbor district","paladin ship crew")),
