        Quest("CH1-067",1,67,"Coal for Carl",category="Khorinis - Masters' Approval Side Quests",giver = "Carl",location="Khorinis - Masters' Approval Side Quests",prerequisites="Chapter 1; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Collect five lumps of coal for harbor blacksmith Carl.",walkthroughSteps=listOf("Ask Carl near the harbor forge what supplies he needs.","Find loose coal around the harbor pier and near the burned cottage on Skip's beach.","Collect at least five pieces of coal.","Deliver them to Carl."),reward="200 XP. The optional locksmith-training conversation with Carl gives a separate 50 XP.",warnings="Follow the prerequisites and visit the named NPC before collecting goods. Source: https://rpgrussia.com/threads/ugol-dlja-karla.66781/",searchTags=listOf("coal for carl","khorinis - masters' approval side quests","local quest giver in khorinis - masters' approval side quests")),
        Quest("CH1-068",1,68,"A Delicacy",category="Khorinis - Masters' Approval Side Quests",giver = "Halvor",location="Khorinis - Masters' Approval Side Quests",prerequisites="Do not turn Halvor in to Lord Andre during Halvor's Fish.",summary="Bring fishmonger Halvor ten oysters from the coastline or nearby merchants.",walkthroughSteps=listOf("Keep Halvor out of prison: do not report him to Lord Andre during Halvor's Fish.","Ask Halvor in Khorinis harbor about the delicacy he wants.","Collect ten oysters from shells or clams on the beach near Skip and around fisherman Farim.","If necessary, buy oysters from Farim after resolving his militia troubles, or from Fenia.","Deliver ten oysters to Halvor."),reward="200 XP and 50 gold.",warnings="Shells may also contain black pearls; keep those for other quests. Source: https://rpgrussia.com/threads/delikates.66782/",searchTags=listOf("a delicacy","khorinis - masters' approval side quests","local quest giver in khorinis - masters' approval side quests")),
        Quest("CH1-069",1,69,"The Extortionist",category="Khorinis - Masters' Approval Side Quests",giver = "Kardif",location="Khorinis - Masters' Approval Side Quests",prerequisites="Chapter 1; talk to the named quest giver, unless the walkthrough specifies a later completion condition.",summary="Help Kardif get rid of Moe, who extorts customers entering the harbor tavern.",walkthroughSteps=listOf("Ask Kardif at the harbor tavern about the thug demanding money at the entrance.","Confront Moe outside the tavern; choose the dialogue explaining that the harbor tavern is open to all.","Defeat Moe in the fistfight if necessary, then speak to him again to make him stop charging people.","Report the resolution to Kardif to unlock daily payment from the tavern."),reward="200 XP for resolving Moe's extortion with him, plus 200 XP from Kardif and a 10-gold daily wage; possible +1 Rhetoric and further fight XP.",warnings="The community guide notes a rhetoric bonus during the first conversation with Moe. Source: https://rpgrussia.com/threads/vymogatel.66783/",searchTags=listOf("the extortionist","khorinis - masters' approval side quests","local quest giver in khorinis - masters' approval side quests")),
        Quest("CH1-070",1,70,"Lehmar's Debtor",category="Khorinis - Masters' Approval Side Quests",giver = "Lehmar",location="Khorinis - Masters' Approval Side Quests",prerequisites="Chapter 1; talk to the named quest giver, unless the walkthrough specifies a later completion condition.",summary="Collect Lehmar's outstanding debt from Mills in the harbor warehouse and recover the swampweed package.",walkthroughSteps=listOf("Speak to moneylender Lehmar about the person who refuses to repay him.","Go to the harbor warehouse beside Garvell's boat shelter and find Mills.","Confront Mills; the documented version provides no peaceful debt-collection outcome, so defeat him.","Loot the swampweed package from Mills and report back to Lehmar.","Keep the package for Cipher's stolen-swampweed quest or Lord Andre's militia swampweed quest."),reward="300 XP and keep the swampweed package for use in Cipher's or Andre's related quest.",warnings="The quest conflicts with sparing Mills; the resulting package can serve other missions. Source: https://rpgrussia.com/threads/dolzhnik-lemara.66869/",searchTags=listOf("lehmar's debtor","khorinis - masters' approval side quests","local quest giver in khorinis - masters' approval side quests")),
        Quest("CH1-071",1,71,"Edda's Statuette",category="Khorinis - Masters' Approval Side Quests",giver = "Edda",location="Khorinis - Masters' Approval Side Quests",prerequisites="Chapter 1; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Find an Innos statuette in Khorinis and bring it to Edda, the harbor cook.",walkthroughSteps=listOf("Ask Edda in Khorinis harbor about the small Innos statuette she wants.","Enter Harad's house beside his forge and look for an Innos statuette; the source discussion corrects an earlier claim that Constantino has one.","Bring the statuette to Edda.","Afterwards Edda gives you free soup daily, and Carl no longer charges his initial strength-training fee."),reward="500 XP, +2 Innos karma and one free Edda soup per day; Carl waives his normal 50-gold strength-training entry fee.",warnings="Follow this quest's branch and item requirements before proceeding. Source: https://rpgrussia.com/threads/statuehtka-ehddy.66784/",searchTags=listOf("edda's statuette","khorinis - masters' approval side quests","local quest giver in khorinis - masters' approval side quests")),
        Quest("CH1-072",1,72,"Tools for Garvell",category="Khorinis - Masters' Approval Side Quests",giver = "Garvell",location="Khorinis - Masters' Approval Side Quests",prerequisites="Chapter 1; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Gather two hammers, one saw and resin to help shipbuilder Garvell finish his boat.",walkthroughSteps=listOf("Speak with Garvell at the Khorinis harbor shipyard.","Collect two hammers, one saw and one portion of resin.","Look for resin on a harbor-building roof; saws beside Martin's pier or near Thorben; a hammer by Thorben's door and another on Skip's beach.","Bring all tools to Garvell."),reward="500 XP and 100 gold.",warnings="Follow the prerequisites and visit the named NPC before collecting goods. Source: https://rpgrussia.com/threads/instrumenty-dlja-garvella.66785/",searchTags=listOf("tools for garvell","khorinis - masters' approval side quests","local quest giver in khorinis - masters' approval side quests")),
        Quest("CH1-073",1,73,"Donations for Daron",category="Khorinis - Marketplace",giver = "Daron",location="Khorinis - Marketplace",prerequisites="Chapter 1; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Donate to Fire Mage Daron for blessings and optional stat bonuses; this is not an ordinary journal quest.",walkthroughSteps=listOf("Find Daron near the Khorinis marketplace and ask about his work in the city.","Donate a sum based on your current gold to receive his one-time initial response.","Continue donating in 200-gold installments if you want the additional mana, learning-point and health bonuses.","Stop when Daron refuses further donations; if you are a Fire Mage novice, this may also unlock Donations for the Monastery."),reward="Initial donation: 200 XP; later 200-gold installments can grant +2 Mana, 500 XP, +2 Learning Points and +10 maximum Health. Low-gold dialogue can give 20 gold and +1 Rhetoric.",warnings="This activity is not recorded as a normal journal quest in the 2026 reference. Costs/bonuses and dialogue access depend on class and previous donations. Source: https://rpgrussia.com/threads/pozhertvovanija-daronu.66811/",searchTags=listOf("donations for daron","khorinis - marketplace","local quest giver in khorinis - marketplace")),
